import unittest

from strip_attribution import owner_body, strip_footer

FOOTER = "_Generated by [Claude Code](https://claude.ai/code)_"
SESSION = "https://claude.ai/code/session_012abc"


class StripFooterTests(unittest.TestCase):
    def test_terminal_footer(self):
        for footer in [FOOTER, "🤖 Generated with Claude Code", SESSION, f"<{SESSION}>",
                       f"Claude-Session: {SESSION}", f"{FOOTER}\n\n{SESSION}"]:
            with self.subTest(footer=footer):
                self.assertEqual(strip_footer(f"Summary.\n\n---\n{footer}\n"), "Summary.\n")
                self.assertEqual(strip_footer(footer), "")

    def test_preserves_nonfooter_text(self):
        for body in [
            f"Summary.\n{FOOTER}",
            f"{FOOTER}\n\nMore to say.",
            f"{FOOTER}\n\n[label]: https://example.com/",
            f"> {FOOTER}", f"> Quote:\n{FOOTER}",
            f"    {FOOTER}", f"- {FOOTER}", f"`{FOOTER}`",
            f"~~~text\n{FOOTER}\n~~~", f"````\n```\n{FOOTER}",
            f"<pre>\n{FOOTER}", f"<blockquote>\n\n{FOOTER}",
            "Generated by [Claude Code](https://example.org/)",
            "Claude-Session: this-is-an-example", f"{SESSION}/extra",
        ]:
            with self.subTest(body=body):
                self.assertEqual(strip_footer(body), body)

    def test_preserves_example_and_line_endings_before_actual_footer(self):
        prefix = f"<!-- Template -->\r\n\r\n```md\r\n{FOOTER}\r\n```\r\n"
        self.assertEqual(strip_footer(prefix + "\r\n---\r\n" + FOOTER), prefix)
        body = "Unchanged.  \r\n\r\n"
        self.assertEqual(strip_footer(body), body)

    def test_removes_only_one_literal_footer_separator(self):
        self.assertEqual(strip_footer("***\n\n---\n" + FOOTER), "***\n")
        self.assertEqual(strip_footer("Title\n---\n" + FOOTER), "Title\n---\n")


class OwnerBodyTests(unittest.TestCase):
    def event(self, pr_author, reviewer, sender):
        return {
            "repository": {"owner": {"id": 1}},
            "sender": {"id": sender},
            "pull_request": {"user": {"id": pr_author}, "body": "pr"},
            "review": {"user": {"id": reviewer}, "body": "review"},
        }

    def test_pr_requires_owner_as_author_and_sender(self):
        self.assertEqual(owner_body("pull_request_target", self.event(1, 2, 1)), "pr")
        for author, sender in [(1, 2), (2, 1), (2, 2)]:
            self.assertEqual(owner_body("pull_request_target", self.event(author, 1, sender)), "")

    def test_review_checks_review_author_independently(self):
        self.assertEqual(owner_body("pull_request_review", self.event(2, 1, 1)), "review")
        for author, sender in [(1, 2), (2, 1), (2, 2)]:
            self.assertEqual(owner_body("pull_request_review", self.event(1, author, sender)), "")

    def test_no_owner_or_unknown_event(self):
        self.assertEqual(owner_body("pull_request_target", {}), "")
        self.assertEqual(owner_body("workflow_dispatch", self.event(1, 1, 1)), "")


if __name__ == "__main__":
    unittest.main()
